import { Component, Inject, Model, Prop, Provide, Vue } from 'vue-property-decorator';

import { ISessionManagementConfirmationTranslations, ISessionManagementDurations, ISessionManagementFieldsTranslations, ISessionManagementFormTranslations, ISessionManagementHelpTranslations, ISessionManagementStringKeyPair, ISessionModel, ISessionSettings, ISessionStatus } from '../../types';
import ButtonIcon from '../button-icon/index.vue';
import InputRow from '../input-row/index.vue';
import LoadingComponent from '../loading/index.vue';
import PrimaryPopup from '../primary-popup/index.vue';

const validMaxBetsPercentages: number[] = [100, 75, 50, 25];
const MIN_BALANCE_FOR_PERCENTAGES: number = 200; // 2 Euro
@Component({
    components: { ButtonIcon, InputRow, LoadingComponent, PrimaryPopup }
})

export default class FormComponent extends Vue {
    public readonly $refs: {
        [key: string]: InputRow
        maxTime: InputRow,
        maxBet: InputRow,
        alertFrequency: InputRow,
        sessionRestriction: InputRow
    };

    @Model()
    public readonly sessionModel: ISessionModel;

    @Prop()
    public readonly sessionStatus: ISessionStatus;

    @Prop()
    public readonly readonly: boolean;

    @Prop()
    public readonly networkPending: boolean;

    @Prop()
    public readonly sessionEndedRecently: boolean;

    @Prop()
    public readonly closeMethod: () => any;

    @Prop()
    public readonly enableDebugSessionValues: boolean;

    @Prop()
    public readonly sessionSettings: ISessionSettings;

    @Prop()
    public readonly translations: ISessionManagementFormTranslations | ISessionManagementConfirmationTranslations;

    @Prop()
    public readonly durationTranslations: ISessionManagementDurations;

    @Prop()
    public readonly helpTranslations: ISessionManagementHelpTranslations;

    @Prop()
    public readonly fieldsTranslations: ISessionManagementFieldsTranslations;

    @Prop()
    public readonly externalPageNavigation: (url: string) => void;

    @Prop()
    public suppressed: boolean;

    @Inject()
    public readonly stringifyTime: (seconds: number) => string;

    @Inject()
    public readonly stringifyBet: (bet: number) => string;

    private errors: string[] = [];

    private formSubmitPreviouslyAttempted: boolean;

    @Provide()
    get errorText(): string {
        return this.fieldsTranslations.errorText;
    }

    get infoText(): string {
        return this.hasFreePlayBalance ? this.translations.freePlay.infoText : this.translations.infoText;
    }

    get maxBetLabel(): string | undefined {
        return this.hasFreePlayBalance ? this.fieldsTranslations.freePlay.balanceText : this.fieldsTranslations.maxBet;
    }

    get maxBetHelp(): string {
        return this.hasFreePlayBalance ? this.helpTranslations.freePlay : this.helpTranslations.maxBet;
    }

    @Provide()
    get helpText(): string {
        return this.helpTranslations.help;
    }

    public get visible(): boolean {
        return this.sessionStatus.SessionEnded && !this.suppressed;
    }

    get maxTimeOptions(): ISessionManagementStringKeyPair[] {
        const options: ISessionManagementStringKeyPair[] = [];

        if (this.enableDebugSessionValues) {
            options.push({ value: 15, string: '15 seconds [DEBUG]' });
        }

        this.sessionSettings.ValidMaxTimes.forEach((time: number) => {
            options.push({ value: time, string: this.stringifyTime(time) });
        });

        return options;
    }

    public get hasFreePlayBalance(): boolean {
        return this.sessionModel.freePlayBalance > 0;
    }

    get maxBetOptions(): ISessionManagementStringKeyPair[] {
        const options: ISessionManagementStringKeyPair[] = [];
        if (this.hasFreePlayBalance) {
            options.push({ value: 0, string: `${(this.sessionModel.freePlayBalance)}` });
            return options;
        }

        if (this.enableDebugSessionValues) {
            options.push({ value: 100, string: '€1 [DEBUG]' });
        }

        this.sessionSettings.ValidMaxBetPercentages = validMaxBetsPercentages;

        for (let index = 0; index < this.sessionSettings.ValidMaxBets.length; index++) {
            const bet = this.sessionSettings.ValidMaxBets[index];
            options.push({ value: bet, string: `${this.sessionSettings.ValidMaxBetPercentages[index]}% (${this.stringifyBet(bet)})` });
            if (bet <= MIN_BALANCE_FOR_PERCENTAGES && index === 0) { // Don't populate rest of percentages if balance is too low
                return options;
            }
        }

        return options;
    }

    get sessionRestrictionOptions(): ISessionManagementStringKeyPair[] {
        const options: ISessionManagementStringKeyPair[] = [];

        if (this.enableDebugSessionValues) {
            options.push({ value: 120, string: '2 minutes [DEBUG]' });
        }

        this.sessionSettings.ValidSessionRestrictions.forEach((time: number) => {
            const timeString: string = time === 0 ? this.durationTranslations.unlimited : this.stringifyTime(time);
            options.push({ value: time, string: timeString });
        });

        return options;
    }

    public mounted(): void {
        this.formSubmitPreviouslyAttempted = false;
        this.$el.scrollTop = 0;
    }

    public submitForm(): void {
        this.formSubmitPreviouslyAttempted = true;
        if (this.readonly || this.validateForm()) {
            this.$emit('form-submitted');
        }
    }

    public itemClicked(linkAddress: string): void {
        this.externalPageNavigation(linkAddress);
    }

    public validateForm(): boolean {
        this.errors = [];

        if (!this.formSubmitPreviouslyAttempted) {
            return true;
        }

        Object.keys(this.$refs).forEach((key: string) => {
            (this.$refs[key] as any).validateField();
        });

        return this.errors.length === 0;
    }

    public onFieldValidation(key: string, success: boolean): void {
        if (!success) {
            this.errors.push(key);
        } else {
            const index = this.errors.indexOf(key);
            if (index > -1) {
                this.errors.splice(index, 1);
            }
        }
    }
}